export function bulkCloseOutEpic(db, input: { project_id; epic_id; reason?; force? }) {
  const project = requireProject(db, input.project_id);
  const epic = requireEpic(db, project.id, input.epic_id);
  const tasks = db.prepare(`SELECT id, status FROM tasks WHERE epic_id = ?`).all(epic.id);

  const cancelled: string[] = [], skipped: string[] = [], conflicted: string[] = [];
  const unblocked = new Set<string>();

  for (const task of tasks) {
    if (task.status === "done" || task.status === "cancelled") { skipped.push(task.id); continue; }
