      const r = cancelTask(db, { task_id: task.id, reason: input.reason, force: input.force });
      cancelled.push(task.id);
      r.unblocked_task_ids.forEach((id) => unblocked.add(id));
    } catch (e) {
      if (e instanceof TaskConflictError) { conflicted.push(task.id); continue; }
      throw e;
    }
  }
  return { cancelled_task_ids: cancelled, skipped_task_ids: skipped, conflicted_task_ids: conflicted, unblocked_task_ids: [...unblocked] };
}
